78	func Compact(content []byte, opts MetadataFields) ([]byte, error) {
79		// Single-object formats (OpenCode, Gemini) must be detected on the raw
80		// content. SliceFromLine operates on newline offsets which would cut a
81		// JSON object mid-value and break parsing. These compactors handle
82		// StartLine internally as a message-index offset.
83		if isOpenCodeFormat(content) {
84			return compactOpenCode(content, opts)
85		}
86	
87		if isGeminiFormat(content) {
88			return compactGemini(content, opts)
89		}
90	
91		truncated := transcript.SliceFromLine(content, opts.StartLine)
92		if truncated == nil {
93			truncated = []byte{}
94		}
95	
96		return compactJSONL(truncated, opts)
97	}
98	
99	// droppedTypes are JSONL entry types that carry no parser-relevant data.
100	var droppedTypes = map[string]bool{
101		"progress":              true,
102		"file-history-snapshot": true,
103		"queue-operation":       true,
104		"system":                true,
105	}
106	
107	// userAliases maps JSONL type/role values to the canonical "user" kind.
108	// Covers Claude Code ("user", "human") and Cursor ("user" via "role" field).
109	var userAliases = map[string]bool{
110		transcript.TypeUser: true,
111		"human":             true,
112	}
113	
114	// normalizeKind returns the canonical entry kind ("user" or "assistant") for a
115	// JSONL transcript line. It checks the "type" field, then falls back to "role".
116	// Returns "" for unrecognised or dropped entries.
117	func normalizeKind(raw map[string]json.RawMessage) string {
118		kind := unquote(raw["type"])
119		if kind == "" {
120			kind = unquote(raw["role"])
121		}
122	
123		if droppedTypes[kind] {
124			return ""
125		}
126		if userAliases[kind] {
127			return transcript.TypeUser
128		}
129		if kind == transcript.TypeAssistant {
130			return transcript.TypeAssistant
131		}
132		return ""
133	}
